INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (0, 'h1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'headline', '', '', 'Thursday''s AI and chip sell-off (Nasdaq 100 -5%, S&P -4%, BTC -5.5%, ETH -7.7%) pushed every market to or below its range low, and all four are in Uptrend weak. BTC and ES printed swing failures at the range low on Friday; ETH and NQ trade below theirs. A week for reclaim trades with Setup Only size, around Tuesday''s CPI.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (1, 'x1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'BTC', 'BTC', 'Exit in force, 200 hold active', '', '', '', '', '', '3 closes below the EMA50 (79,580) and the EMA200 (76,471). Any long is a range trade only. Shorts are held until two closes back above 76,471.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (2, 'x2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'ETH', 'ETH', 'Exit in force, 200 hold active', '', '', '', '', '', 'Confirmed Bearish since 9 Oct, 3 closes below the EMA200 (2,313). Shorts are held until two closes back above it.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (3, 'x3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'SPX', 'ES (S&P)', 'Exit rule hit 6 Nov', '', '', '', '', '', 'Two cash closes below the EMA50 (7,650; about 7,680 on ES) and the weekly trend turned Below both (pay attention). Friday closed 0.3% back above the EMA200 (7,357; about 7,386 on ES): Monday''s close is the second.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (4, 'x4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'NDX', 'NQ (est.)', 'Exit in force, 200 hold active', '', '', '', '', '', '7 closes below the EMA50 and 2 below the EMA200 (28,130; about 28,240 on NQ): shorts are held until two closes back above it. Weekly Below both for 4 weeks.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (5, 'l1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'BTC', 'BTC', 'Range low sweep', '4H sweep of 75,000 that closes back above (the app alerts it), or two 4H closes back above 75,000 after losing it', 'Below the sweep low (Friday''s low 74,722)', 'EMA200 76,471 first (about 1.7R), mid 81,000 (about 8R) from 75,300 with a stop at 74,600', 'Setup Only (Uptrend weak, below EMA200)', '75000', 'Friday''s daily swing failure at 75,000 already printed; price has stalled under the EMA200 since. Two daily closes above 76,471 end the 200 hold rule and upgrade this setup.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (6, 'l2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'ETH', 'ETH', 'Monthly open reclaim', 'Two 1H closes above 2,255 (monthly open), your clean-range 1H exception', 'Below the range lows of 5 and 6 Nov (about 2,195)', 'Range low 2,350 (about 1.4R), mid 2,528 (about 4R), yearly open 3,000 (about 11R) from 2,260', 'Setup Only, counter-trend (confirmed Bearish)', '2255', 'Overhead before 2,350: EMA12 2,288, EMA200 2,313, EMA21 2,328. Your alerts check 4H closes, so the 1H trigger is yours to watch.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (7, 'l3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'ETH', 'ETH', 'Range low reclaim (add)', 'Two 4H closes back above 2,350, only with l2 open and in profit', 'First stop to break-even; the add''s stop below the EMA200 (2,313)', 'Mid 2,528, then yearly open 3,000', 'Add, Setup Only', '2350', 'Back above the range low and the EMA200: two daily closes there end the 200 hold rule.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (8, 'l8', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'ETH', 'ETH', 'Retracement zone hold', '4H sweep of 1,986 or 1,951 that closes back above (alerted), or two 4H closes back above 2,006 after trading in the zone', 'Below the sweep low, at the latest under 1,935', '2,178 (about 3R from 1,990 with a stop at 1,935), monthly open 2,255 (about 5R)', 'Setup Only, counter-trend (confirmed Bearish)', '1985.88', 'Your retracement zone 1,951 to 1,986, where the 0.618 to 0.65 retracement of the June to September rally (1,510 to 2,807) sits at 2,006 to 1,964; 10 Nov''s low 2,006 tagged the 0.618. A daily close below 1,951 opens 1,749, then the 1,427 to 1,512 demand zone.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (9, 'l4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'SPX', 'ES (S&P)', 'Range low swing failure', 'Friday swept 7,329 and closed back above (low 7,322, close 7,402). Enter only on a hold of 7,329 on a 4H close after a retest, or a fresh sweep and reclaim', 'Below 7,322 (Friday''s low)', 'EMA100 7,608 and mid 7,620 (about 2.4R from 7,400 with a stop at 7,310)', 'Setup Only (weekly Below both, Uptrend weak)', '7329.25', 'Two daily closes below 7,329 end this setup and bring 7,045 into play (-4.8%).');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (10, 'l5', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'SPX', 'ES (S&P)', 'Sweep of 7,045', 'Sweep of 7,045 that closes back above, only after a breakdown below 7,329', 'Below the sweep', 'Range low 7,329 (+4%)', 'Setup Only, counter-trend', '7045', 'Your next support below the range.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (11, 'l6', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'NDX', 'NQ (est.)', 'Range low reclaim', 'Two 4H closes back above 27,220 on your NQ1! chart', 'Below the reclaim low', 'EMA200 about 28,240 (+3.7%), then mid 29,000', 'Setup Only (below EMA200, 200 hold active)', '27220', 'NQ is estimated at 27,073 on Friday''s close, 0.5% below. The alerts cannot see NQ 4H candles (no NQ intraday data), so watch this one on your chart; daily closes back above 27,220 do alert.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (12, 'l7', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'NDX', 'NQ (est.)', 'Downside bounce levels', 'Sweep of 26,393 or 25,455 that closes back above', 'Below the sweep', 'Range low 27,220', 'Setup Only, counter-trend', '26393', '26,393 is 2.5% below Friday''s estimate; Thursday''s estimated low was 26,704.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (13, 's1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'short', '', '', 'ES rejection at mid 7,620 (conditional)', '', '', '', '', '', 'Short a rally into 7,620 that is rejected (high above mid, daily close back below), stop above the high, target the range low 7,329. Mid, EMA100 (7,608) and EMA21 (7,654) stack there. Judgment: mid-range shorts after a failed high tested +0.3 to +1.4R, but on only 5 to 6 trades.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (14, 's2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'short', '', '', 'No new shorts at the lows', '', '', '', '', '', 'Every market sits at or below its range low, so a stop above the range is far from the target. Retests of a broken range low tested -0.14R. Existing shorts stay on under the 200 hold rule.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (15, 'r1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'No front-running. A touch of a level is not a trigger: wait for the close back above.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (16, 'r2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'All longs are counter-trend: all four markets are in Uptrend weak. Your tested trend edge is weak in Range and Bearish regimes, so Setup Only size and fewer trades.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (17, 'r3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'BTC, ETH, ES and NQ fell together on 5 Nov. Count open longs as one correlated bet and cap their combined risk.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (18, 'r4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'No new entries in the hour around CPI (Tue 14:30) and PPI (Fri 14:30).', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (19, 'e1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Tue 10 Nov 14:30 Zurich: US CPI (Oct), forecast 0.3% m/m, core 0.2% m/m', '', '', '', '', '', '');
