INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (22, 'e4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Fed speakers every day (Waller Tue 10:00, then Logan, Bowman, Goolsbee, Daly, Williams)', '', '', '', '', '', '');
