INSERT INTO range_levels_history (asset, data, saved_at, saved_by) VALUES ('ETH', '{"asset":"ETH","range_high":"2780","mid":"2528","range_low":"2350","set_on":"2026-11-10","note":"Below the range but OK: retracement zone 1951-1986 needs to hold. Reclaim monthly open 2255 with 2 one hr closes above = long trigger, then reclaim range low 2350 to compound. Target yearly open 3k. Below 1951: 1749, then 1427-1512.","proxy_ratio":"","watch_levels":"2178.61;1985.88;1950.74;1749.28;1512.17;1427.02","long_trigger_4h":"2255","trigger_tf":"1H"}', '2026-11-10T22:11:28.659Z', 'Claude (Marc gave the levels in chat)');
